"""Generate/check the native header from the reviewed WeChat version registry."""
from __future__ import annotations

import argparse
import sys
from pathlib import Path

ROOT = Path(__file__).resolve().parents[1]
sys.path.insert(0, str(ROOT / "src"))
from companion_wechat.native.versions import CANONICAL, PROFILES  # noqa: E402


def render():
    lines = [
        "#pragma once", "// Generated by scripts/generate_wechat_versions.py; edit versions.json instead.",
        "struct CoreBuild {", "    LONG id;", "    uint64_t bytes;",
        "    uint32_t timestamp, image_size;", "    unsigned char sha256[32];", "};",
        "static constexpr CoreBuild core_builds[] = {",
    ]
    for p in PROFILES:
        digest = ",".join(f"0x{b:02x}" for b in bytes.fromhex(p["sha256"]))
        lines.append(f'    {{{p["id"]}, {p["size"]}ull, {p["timestamp"]:#x}, {p["image_size"]:#x}, {{{digest}}}}},')
    lines.extend([
        "};", "static volatile LONG core_profile_id = 0;",
        "static bool core_size_supported(uint64_t bytes) {",
        "    for (const auto& build: core_builds) if (build.bytes == bytes) return true;",
        "    return false;", "}",
        "static bool core_select_build(uint64_t bytes, const unsigned char* digest,",
        "                              uint32_t timestamp, uint32_t image_size) {",
        "    InterlockedExchange(&core_profile_id, 0);",
        "    for (const auto& build: core_builds) {",
        "        if (build.bytes == bytes && build.timestamp == timestamp && build.image_size == image_size &&",
        "                std::equal(build.sha256, build.sha256+32, digest)) {",
        "            InterlockedExchange(&core_profile_id, build.id);", "            return true;", "        }",
        "    }", "    return false;", "}",
        "static uintptr_t core_rva(uintptr_t legacy) {",
        "    switch (InterlockedCompareExchange(&core_profile_id, 0, 0)) {",
    ])
    for p in PROFILES:
        lines.extend([f'        case {p["id"]}: // {p["version"]}', "            switch (legacy) {"])
        for name, canonical in CANONICAL.items():
            lines.append(f'                case {canonical:#x}: return {p["rvas"][name]:#x}; // {name}')
        lines.extend(["                default: return 0;", "            }"])
    lines.extend([
        "        default: return 0;", "    }", "}",
        "static uintptr_t core_address(uintptr_t base, uintptr_t legacy) {",
        "    const auto rva = core_rva(legacy);", "    return rva ? base + rva : 0;", "}", "",
    ])
    return "\n".join(lines)


def main():
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--check", action="store_true")
    args = parser.parse_args()
    target = ROOT / "src/companion_wechat/native/core_version.h"
    content = render()
    if args.check:
        if not target.is_file() or target.read_text(encoding="utf8") != content:
            raise SystemExit("WeChat header is stale; run scripts/generate_wechat_versions.py")
    else:
        target.write_text(content, encoding="utf8", newline="\n")


if __name__ == "__main__":
    main()
